    "law": "oram2026",
    "topic": "ORAM 2026: recursos humanos e controlo",
    "subtopic": "Atribuição de incentivos aos conservadores de registos da Região Autónoma da Madeira",
    "familyId": "oram2026:revisao-oram-rh-final-57",
