    "law": "oram2026",
    "topic": "ORAM 2026: recursos humanos e controlo",
    "subtopic": "Regime de chamada dos trabalhadores do Serviço de Apoio Funcional",
    "familyId": "oram2026:revisao-oram-rh-final-58",
